import assert from 'node:assert/strict';
import { performance } from 'node:perf_hooks';
import { uniqueTags } from '../src/tags.js';

const mode = process.argv[2];
function check(input, expected) {
  const original = [...input];
  Object.freeze(input);
  const result = uniqueTags(input);
  assert.ok(Array.isArray(result));
  assert.deepEqual(result, expected);
  assert.deepEqual(input, original);
}
if (mode === 'case') {
  check(['JS', 'Node', 'js', 'NODE', 'css'], ['JS', 'Node', 'css']);
  check(['js', 'JS', 'Js', 'jS'], ['js']);
  check(['NODE', 'node', 'Node', 'CSS', 'css', 'JS'], ['NODE', 'CSS', 'JS']);
  check(['', '', 'A', 'a', ' a', ' A', 'a ', 'A ', 'ab', 'AB', 'a-b', 'A-B'], ['', 'A', ' a', 'a ', 'ab', 'a-b']);
  check(['__proto__', '__PROTO__', 'constructor', 'CONSTRUCTOR', 'toString', 'TOSTRING'], ['__proto__', 'constructor', 'toString']);
  let seed = 123456789;
  const random = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed; };
  const tags = [];
  for (let i = 0; i < 20000; i++) {
    const base = `topic-${random() % 2500}-js`;
    tags.push([...base].map(c => (random() & 8) ? c.toUpperCase() : c).join(''));
  }
  const seen = new Set();
  const expected = tags.filter(tag => {
    const key = tag.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  check(tags, expected);
} else if (mode === 'preserve') {
  check([], []);
  check(['node', 'js', 'node', 'css', 'js'], ['node', 'js', 'css']);
  check(['z', 'a', 'm', 'z', 'a', 'b'], ['z', 'a', 'm', 'b']);
  check(['', ' ', '', '  ', ' '], ['', ' ', '  ']);
  check(['__proto__', 'constructor', 'toString', '__proto__'], ['__proto__', 'constructor', 'toString']);
  const tags = Array.from({ length: 100000 }, (_, i) => `tag-${i}`);
  check([...tags, ...tags], tags);
} else if (mode === 'speed' || mode === 'bench') {
  // Mostly distinct strings penalize quadratic scans; build inputs outside timing.
  const tags = Array.from({ length: 200000 }, (_, i) => `Topic-${i}-JavaScript`);
  for (let i = 0; i < 5; i++) uniqueTags(tags.slice(0, 1000));
  const times = [];
  for (let i = 0; i < 3; i++) {
    const start = performance.now();
    const result = uniqueTags(tags);
    times.push(performance.now() - start);
    assert.deepEqual(result, tags);
  }
  const median = times.sort((a, b) => a - b)[1];
  if (mode === 'speed') assert.ok(median < 600, `200,000 tags took ${median.toFixed(1)}ms (limit 600ms)`);
  console.log(median.toFixed(3));
} else {
  throw new Error('unknown check mode');
}
